import{_ as a,a0 as r,w as u,s as p,ao as o,I as e,x as l,a1 as n,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"Linux 內核測試與調試（3） | LCTT x X-CMD","titleTemplate":false,"description":"Linux 內核測試與調試（3） | LCTT (201408) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 內核測試與調試（3） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 內核測試與調試（3） | LCTT (201408) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201408/20140718 Linux Kernel Testing and Debugging 3","title":"Linux 內核測試與調試（3）","tag":"201408","desc":""},"relativePath":"201408/20140718 Linux Kernel Testing and Debugging 3.md","filePath":"[post].md"}'),d={name:"201408/20140718 Linux Kernel Testing and Debugging 3.md"};function g(f,t,m,b,k,T){const i=r("Link");return u(),p("div",null,[t[16]||(t[16]=o('<h1 id="linux-內核測試與調試-3" tabindex="-1">Linux 內核測試與調試（3） <a class="header-anchor" href="#linux-內核測試與調試-3" aria-label="Permalink to “Linux 內核測試與調試（3）”">​</a></h1><h3 id="基本測試" tabindex="-1">基本測試 <a class="header-anchor" href="#基本測試" aria-label="Permalink to “基本測試”">​</a></h3><p>安裝好內核後，試試能不能啓動它。能啓動的話，檢查 dmesg 看看有沒有隱藏的錯誤。試試下面的功能：</p><ul><li>網絡（Wifi 或者網線）是否可用？</li><li>ssh 是否可用？</li><li>使用 ssh 遠程傳輸文件。</li><li>使用 git clone 和 git pull 命令。</li><li>用用網絡瀏覽器。</li><li>查看 email。</li><li>使用 ftp, wget 等軟件下載文件。</li><li>播放音頻視頻文件。</li><li>連上 USB 鼠標等設備。</li></ul><h3 id="檢查內核日誌" tabindex="-1">檢查內核日誌 <a class="header-anchor" href="#檢查內核日誌" aria-label="Permalink to “檢查內核日誌”">​</a></h3><p>使用 dmesg 查看隱藏的問題，對於定位新代碼帶來的 bug 是一個好方法。一般來説，dmesg 不會輸出新的 crit, alert, emerg 級別的錯誤信息，也不應該出現新的 err 級別的信息。你要注意的是那些 warn 級別的日誌信息。請注意 warn 這個級別的信息並不是壞消息，新代碼帶來新的警告信息，不會給內核帶去嚴重的影響。</p><ul><li>dmesg -t -l emerg</li><li>dmesg -t -l crit</li><li>dmesg -t -l alert</li><li>dmesg -t -l err</li><li>dmesg -t -l warn</li><li>dmesg -t -k</li><li>dmesg -t</li></ul>',7)),e("p",null,[t[1]||(t[1]=l("下面的腳本運行了上面的命令，並且將輸出保存起來，以便與老的內核的 dmesg 輸出作比較（LCTT：老內核的 dmesg 輸出在本系列的",-1)),n(i,{href:"http://linux.cn/article-3629-1.html"},{default:s(()=>[...t[0]||(t[0]=[l("第二篇文章",-1)])]),_:1}),t[2]||(t[2]=l("中有介紹）。然後運行 diff 命令，查看新老內核 dmesg 日誌之間的不同。這個腳本需要輸入老內核版本號，如果不輸入參數，它只會生成新內核的 dmesg 日誌文件後直接退出，不再作比較（LCTT：話是這麼説沒錯，但點開腳本一看，沒輸參數的話，這貨會直接退出，連新內核的 dmesg 日誌也不會保存的）。如果 dmesg 日誌有新的警告信息，表示新發布的內核有漏網之“蟲”，這些 bug 逃過了自測和系統測試。你要看看，那些警告信息後面有沒有棧跟蹤信息？也許這裏有很多問題需要你進一步調查分析。",-1))]),e("ul",null,[e("li",null,[n(i,{href:"http://linuxdriverproject.org/mediawiki/index.php/Dmesg_regression_check_script"},{default:s(()=>[...t[3]||(t[3]=[e("strong",null,"dmesg 測試腳本",-1)])]),_:1})])]),t[17]||(t[17]=e("h3",{id:"壓力測試",tabindex:"-1"},[l("壓力測試 "),e("a",{class:"header-anchor",href:"#壓力測試","aria-label":"Permalink to “壓力測試”"},"​")],-1)),t[18]||(t[18]=e("p",null,"執行壓力測試的一個好辦法是同時跑三四個內核編譯任務。下載各種版本的內核，同時編譯它們，並記錄時間。比較新內核跑壓力測試和老內核跑壓力測試所花的時間，然後可以定位新內核的性能。如果新內核跑壓力測試的時間比老內核的更長，説明新內核的部分模組性能退步了。性能問題很難調試出來。第一步是找出哪裏導致的性能退步。同時跑多個內核編譯任務對檢測內核整體性能來説是個好方法，但是這種方法涵蓋了多個內核模組，比如內存管理、文件系統、DMA、驅動等（LCTT：也就是説，這種壓力測試沒辦法定位到是哪個模組造成了性能的下降）。",-1)),t[19]||(t[19]=e("pre",null,[e("code",null,`time make all
`)],-1)),t[20]||(t[20]=e("h3",{id:"內核測試工具",tabindex:"-1"},[l("內核測試工具 "),e("a",{class:"header-anchor",href:"#內核測試工具","aria-label":"Permalink to “內核測試工具”"},"​")],-1)),t[21]||(t[21]=e("p",null,"我們可以在 Linux 內核本身找到多種測試方法。下面介紹一個很好用的功能測試工具集： ktest 套件",-1)),t[22]||(t[22]=e("p",null,"ktest 是一個自動測試套件，它可以提供編譯安裝啓動內核一條龍測試服務，也可以跑交叉編譯測試，前提是你的系統有安裝交叉編譯所需要的軟件。ktest 依賴於 flex 和 bison。詳細信息請參考放在 tools/testing/ktest 目錄下的文檔，你可以自學成材。另外還有一些參考資料教你怎麼使用 ktest：",-1)),e("ul",null,[e("li",null,[n(i,{href:"http://elinux.org/Ktest#Git_Bisect_type"},{default:s(()=>[...t[4]||(t[4]=[e("strong",null,"ktest-eLinux.org",-1)])]),_:1})])]),t[23]||(t[23]=o(`<h3 id="tools-testing-selftests-套件" tabindex="-1">tools/testing/selftests 套件 <a class="header-anchor" href="#tools-testing-selftests-套件" aria-label="Permalink to “tools/testing/selftests 套件”">​</a></h3><p>我們來玩玩自測吧。內核源碼的多個子系統都有自己的自測工具，到目前為止，斷點、cpu熱插拔、efivarfs、IPC、KCMP、內存熱插拔、mqueue、網絡、powerpc、ptrace、rcutorture、定時器和虛擬機子系統都有自測工具。另外，用户態內存的自測工具可以利用 test_user_copy 模組來測試用户態內存到內核態的拷貝過程。下面的命令演示瞭如何使用這些測試工具：</p><p>編譯測試：</p><pre><code>make -C tools/testing/selftests 
</code></pre><p>測試全部：（有些測試需要 root 權限，你需要以 root 用户登入系統然後運行命令）</p><pre><code>make -C tools/testing/selftests run_tests 
</code></pre><p>只測試單個子系統：</p><pre><code>make -C tools/testing/selftests TARGETS=vm run_tests 
</code></pre><h3 id="tools-testing-fault-injection-套件" tabindex="-1">tools/testing/fault-injection 套件 <a class="header-anchor" href="#tools-testing-fault-injection-套件" aria-label="Permalink to “tools/testing/fault-injection 套件”">​</a></h3><p>在 tools/testing 目錄下的另一個測試套件是 fault-injection。failcmd.sh 腳本用於檢測 slab 和內存頁分配器的錯誤。這些工具可以測試內核能否很好地從錯誤狀態中恢復回來。這些測試需要用到 root 權限。下面簡單介紹了一些當前能提供的錯誤檢測方法。隨着錯誤檢測方法的增加，這份名單也會不斷增長。最新的名單請參考 Documentation/fault-injection/fault-injection.txt 文檔。</p><p>failslab （默認選項）</p><blockquote><p>產生 slab 分配錯誤。作用於 kmalloc(), kmem_cache_alloc() 等函數（LCTT：產生的結果是調用這些函數就會返回失敗，可以模擬程序分不到內存時是否還能穩定運行下去）。</p></blockquote><p>fail_page_alloc</p><blockquote><p>產生內存頁分配的錯誤。作用於 alloc_pages(), get_free_pages() 等函數（LCTT：同上，調用這些函數，返回錯誤）。</p></blockquote><p>fail_make_request</p><blockquote><p>對滿足條件（可以設置 /sys/block//make-it-fail 或 /sys/block///make-it-fail 文件）的磁盤產生 IO 錯誤，作用於 generic_make_request() 函數（LCTT：所有針對這塊磁盤的讀或寫請求都會出錯）。</p></blockquote><p>fail_mmc_request</p><blockquote><p>對滿足條件（可以設置 /sys/kernel/debug/mmc0/fail_mmc_request 這個 debugfs 屬性）的磁盤產生 MMC 數據錯誤。</p></blockquote><p>你可以自己配置 fault-injection 套件的功能。fault-inject-debugfs 內核模組在系統運行時會在 debugfs 文件系統下面提供一些屬性文件。你可以指定出錯的概率，指定兩個錯誤之間的時間間隔，當然本套件還能提供更多其他功能，具體請查看 Documentation/fault-injection/fault-injection.txt。 Boot 選項可以讓你的系統在 debugfs 文件系統起來之前就可以產生錯誤，下面列出幾個 boot 選項：</p><ul><li>failslab=</li><li>fail_page_alloc=</li><li>fail_make_request=</li><li>mmc_core.fail_request=[interval],[probability],[space],[times]</li></ul><p>fault-injection 套件提供接口，以便增加新的功能。下面簡單介紹下增加新功能的步驟，詳細信息請參考上面提到過的文檔：</p><p>使用 DECLARE_FAULT_INJECTION(name) 定義默認屬性；</p><blockquote><p>詳細信息可查看 fault-inject.h 中定義的 struct fault_attr 結構體。</p></blockquote><p>配置 fault 屬性，新建一個 boot 選項;</p><blockquote><p>這步可以使用 setup_fault_attr(attr, str) 函數完成，為了能在系統啓動的早期產生錯誤，添加一個 boot 選項這一步是必須要有的。</p></blockquote><p>添加 debugfs 屬性；</p><blockquote><p>使用 fault_create_debugfs_attr(name, parent, attr) 函數，為新功能添加新的 debugfs 屬性。</p></blockquote><p>為模組設置參數；</p><blockquote><p>為模組添加一些參數，對於配置錯誤屬性來説是一個好主意，特別是當新功能的應用範圍受限於單個內核模組的時候（LCTT：不同內核，你的新功能可能需要不同的測試參數，通過設置參數，你的功能可以不必為了迎合不同內核而每次都重新編譯一遍）。</p></blockquote><p>添加一個鈎子函數到錯誤測試的代碼中。</p><blockquote><p>should_fail(attr, size) —— 當這個鈎子函數返回 true 時，用户的代碼就應該產生一個錯誤。</p></blockquote><p>應用程序使用這個 fault-injection 套件可以指定某個具體的內核模組產生 slab 和內存頁分配的錯誤，這樣就可以縮小性能測試的範圍。</p><hr>`,33)),e("p",null,[t[6]||(t[6]=l("via: ",-1)),n(i,{href:"http://www.linuxjournal.com/content/linux-kernel-testing-and-debugging?page=0,2"},{default:s(()=>[...t[5]||(t[5]=[l("http://www.linuxjournal.com/content/linux-kernel-testing-and-debugging?page=0,2",-1)])]),_:1})]),e("p",null,[t[9]||(t[9]=l("譯者：",-1)),n(i,{href:"https://github.com/bazz2"},{default:s(()=>[...t[7]||(t[7]=[l("bazz2",-1)])]),_:1}),t[10]||(t[10]=l(" 校對：",-1)),n(i,{href:"https://github.com/wxy"},{default:s(()=>[...t[8]||(t[8]=[l("wxy",-1)])]),_:1})]),e("p",null,[t[13]||(t[13]=l("本文由 ",-1)),n(i,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[11]||(t[11]=[l("LCTT",-1)])]),_:1}),t[14]||(t[14]=l(" 原創翻譯，",-1)),n(i,{href:"http://linux.cn/"},{default:s(()=>[...t[12]||(t[12]=[l("Linux中國",-1)])]),_:1}),t[15]||(t[15]=l(" 榮譽推出",-1))])])}const L=a(d,[["render",g]]);export{C as __pageData,L as default};
